(1270, 2, 'MCQ', 'Junior employees gain immense value from spontaneous mentoring', NULL, NULL, 1, 3, NULL, 'click', 'null', '9dd4f6fe-9b97-4cb5-ba02-0e1b7689b42a', 'set6'),
