(1679, 4, 'DRAG_DROP_ORDERING', 'an archival document destruction protocol\n\n', NULL, NULL, 4, 0, NULL, 'click', '{"items": [{"text": "If you intend to dispose of confidential client dossiers, please adhere to these security steps.", "order": 1}, {"text": "Before you can transport any sensitive files to the shredding bay, you must secure an official destruction clearance.", "order": 2}, {"text": "You can initiate this disposal request on the internal records database during business hours.", "order": 3}, {"text": "Our central compliance software will log an approved destruction order once legal review confirms eligibility.", "order": 4}, {"text": "Upon presenting your compliance authorization, the archives manager will release the designated secure bin.", "order": 5}, {"text": "Please lock the mobile disposal bin immediately with your supervisor\'s tamper-evident security seal.", "order": 6}], "drag_items": ["Item 1"], "drop_zones": ["Zone 1"], "fixed_sentence": "If you intend to dispose of confidential client dossiers, please adhere to these security steps.", "correct_mapping": {"0": 0}}', 'acea48b4-a015-4f8a-a912-3fcc12605127', 'set8'),
