(1691, 4, 'MCQ', '(\'19\', \'Who thinks the office chairs and electrical fixtures need immediate physical repairs?\')', NULL, NULL, 2, 0, NULL, 'select', 'null', 'c40fd804-0ea8-4c6a-8e7e-1dd8f7305a6f', 'set8'),
