(1693, 4, 'MCQ', '(\'21\', \'Who experiences regular technical breakdowns with shared office hardware and connections?\')', NULL, NULL, 2, 0, NULL, 'select', 'null', 'c40fd804-0ea8-4c6a-8e7e-1dd8f7305a6f', 'set8'),
