(1695, 4, 'QUESTION_FORM', 'Read the passage quickly. Choose a heading from the list for each numbered paragraph. There is one heading that you do not need. The first one is done for you.', NULL, NULL, 0, 0, NULL, 'click', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8'),
(1696, 4, 'QUESTION_FORM', 'The First Transcontinental Railroad', NULL, NULL, 0, 0, NULL, 'click', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8'),
(1697, 4, 'MCQ', 'Paragraph 1:\n\nRailroad promoters believed that an overland rail link would bind distant territories together while opening inland commerce across western territories. Prominent civil engineers argued that gradual river grades provided natural rail corridors through mountainous divides. However, skeptical financiers and rival transport lobbies declared that boring tunnels through towering granite ranges was an impossible commercial gamble. They claimed that brutal winter snowstorms and desert heat would inevitably bankrupt the enterprise. Railroad leaders insisted that aggressive mechanical excavation would conquer any barrier.', NULL, NULL, 2, 0, NULL, 'select', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8'),
(1698, 4, 'MCQ', 'Paragraph 2:\n\nThe rail companies faced massive logistical preparation before laying a single tie. The western line had to ship every locomotive, iron rail, and spike around South America by sea, requiring months of advance planning. The eastern line required colossal supply trains to transport thousands of cords of timber, coal, and dynamite across Nebraska prairies. Temporary construction cities sprang up alongside moving railheads to house thousands of laborers. The crews required tremendous food supplies, consuming immense shipments of salted pork, tinned provisions, and fresh beef driven alongside railhead camps.', NULL, NULL, 2, 0, NULL, 'select', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8'),
(1699, 4, 'MCQ', 'Paragraph 3:\n\nThe construction workforce—comprising thousands of determined Chinese immigrants on the western route, joined by Irish veterans and freedmen on the eastern plains—was organized with military efficiency. Equipped with black powder, hand drills, horse-drawn scrapers, and surveying transits, specialized grading gangs worked around the clock to blast cliff ledges and grade roadbeds weeks ahead of tracklayers.', NULL, NULL, 2, 0, NULL, 'select', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8');
INSERT INTO `questions` (`id`, `module_id`, `question_type`, `question_text`, `audio_script`, `media_url`, `marks`, `order_index`, `recording_duration`, `display_type`, `drag_drop_data`, `group_id`, `question_set`) VALUES
(1700, 4, 'MCQ', 'Paragraph 4:\n\nCrews confronted extreme hardship crossing the Sierra Nevada mountains, where workers chiseled summit tunnels through solid rock while surviving catastrophic avalanches under thirty-foot snowdrifts. On the eastern plains, tracklayers raced across parched basins under scorching summer heat. Overcoming daunting logistics and hostile terrain, the two railheads converged at Promontory Summit, Utah. On May 10, 1869, a ceremonial golden spike was driven home, reducing a grueling six-month overland journey to just six days.', NULL, NULL, 2, 0, NULL, 'select', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8'),
(1701, 4, 'MCQ', 'Paragraph 5:\n\nThe celebration following the driving of the Golden Spike was tempered by heated controversy and financial scrutiny. Journalists exposed corrupt financing schemes and fraudulent stock manipulation by railway executives. Land rights advocates criticized the immense government land grants ceded to private rail barons. Nevertheless, commerce statistics soon confirmed that the cross-continental line slashed freight costs and accelerated nationwide settlement, transforming industrial output.', NULL, NULL, 2, 0, NULL, 'select', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8'),
(1702, 4, 'MCQ', 'Paragraph 6:\n\nIn the decades following the golden spike ceremony, modern rail corporations continually upgraded the historic transcontinental alignment. Engineers replaced wooden trestles with steel viaducts, constructed massive snowsheds, and bored deeper, electrified tunnels to bypass steep grades. Modern transport historians and train enthusiasts frequently retrace the original roadbed, using satellite photography to map surviving grade remnants.', NULL, NULL, 2, 0, NULL, 'select', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8'),
(1703, 4, 'MCQ', 'Paragraph 7:\n\nThe dramatic story of the transcontinental railroad has captured the historical imagination for over a century. Numerous historical biographies, folk songs, and classic films recount the monumental struggle of the laborers who built the line. Today, the historic meeting point at Promontory Summit is preserved as a national historical park, standing as a testament to pioneer human determination and engineering triumph.', NULL, NULL, 2, 0, NULL, 'select', 'null', '1369afe2-526d-467d-9315-7dc221d56c05', 'set8'),
(1861, 4, 'QUESTION_FORM', 'Read the email given below. Choose one word from the drop-down list for each gap. The first one is done for you.', NULL, NULL, 0, 0, NULL, 'click', 'null', 'c6cb1afe-08d0-4dee-845b-08347a76ae17', 'set9'),
